function toStyleMap(str: string): Map<string, string> {
  const styleMap: Map<string, string> = new Map()
  for (const item of str.split(';')) {
    let [key, value] = item.split(':')
    key = key.trim()
    value = value && value.trim()
    if (key && value) {
      styleMap.set(key, value)
    }
  }
  return styleMap
}

function isMapEqual(a: Map<string, string>, b: Map<string, string>): boolean {
  if (a.size !== b.size) {
    return false
  }
  for (const [key, value] of a) {
    if (value !== b.get(key)) {
      return false
    }
  }
  return true
}

function resolveCssVars(
  instance: ComponentInternalInstance,
  vnode: VNode,
  expectedMap: Map<string, string>,
) {
  let current: ComponentInternalInstance | null = instance
  let currentVNode: VNode | null = vnode

  while (current) {
    const root = current.subTree
    let shouldApply = false

    if (root && currentVNode === root) {
      shouldApply = true
    } else if (
      root &&
      root.type === Fragment &&
      (root.shapeFlag & ShapeFlags.ARRAY_CHILDREN) !== 0
    ) {
      const fragmentChildren = root.children
      const childList = fragmentChildren as VNode[]
      const childCount = childList.length
      for (let i = 0; i < childCount; i++) {
        const child = childList[i]
        if (child) {
          if (child === currentVNode) {
            shouldApply = true
            break
          }
        }
      }
    }

    if (shouldApply && current.getCssVars) {
      let cssVars = current.getCssVars()
      if (isReactive(cssVars)) {
        cssVars = toRaw(cssVars)
      }

      const collected: Record<string, string> = {}
      for (const key in cssVars) {
        const raw = cssVars[key]
        const displayed = toDisplayString(raw)
        let value: string
        if (raw == null) {
          value = String(raw)
        } else {
          value = displayed
        }
        const prefix = '--'
        const cssKey = `${prefix}${key}`
        collected[cssKey] = value
      }

      const normalizedCollected = normalizeStyle(collected)
      const serialized = stringifyStyle(
        normalizedCollected as Record<string, string | number>,
      )

      if (serialized) {
        const parsed = parseStringStyle(serialized)
        for (const parsedKey in parsed) {
          const parsedValue = parsed[parsedKey]
          expectedMap.set(parsedKey, String(parsedValue))
        }
      } else {
        for (const cssKey in collected) {
          const collectedValue = collected[cssKey]
          expectedMap.set(cssKey, collectedValue)
        }
      }
    }

    if (currentVNode === root) {
      const hostVNode = current.vnode
      const parentInstance = current.parent
      currentVNode = hostVNode
      current = parentInstance
    } else {
      current = null
    }
  }
}

