import {
  createSSRApp,
  defineComponent,
  h,
  useCssVars,
} from '../packages/runtime-core/src'
import { createApp, createHydrationFunctions } from '../packages/runtime-dom/src'

function mountWithHydration(template: string, render: () => any) {
  const container = document.createElement('div')
  container.innerHTML = template
  const app = createSSRApp({ setup: render })
  const { hydrate } = createHydrationFunctions()
  // mimic app.mount with hydrate
  const vnode = app._createVNode(app._component)
  vnode.appContext = app._context
  hydrate(vnode, container)
  return container
}

describe('repro #11739', () => {
  beforeEach(() => {
    // @ts-expect-error
    document = undefined
  })

  test('css vars fallthrough + child style binding', () => {
    const container = document.createElement('div')
    container.innerHTML = `<div style="display:flex;--xxxxx-background-color:blue;"><div>Hello</div></div>`
    const app = createSSRApp({
      setup() {
        useCssVars(() => ({
          'xxxxx-background-color': 'blue',
        }))
        return () => h(Child, { class: 'parent' })
      },
    })
    const Child = defineComponent({
      props: { display: { type: String, default: 'flex' } },
      setup(props) {
        return () =>
          h('div', { style: { display: props.display } }, 'Hello')
      },
    })
    app.mount(container)
    expect(`Hydration style mismatch`).not.toHaveBeenWarned()
  })
})

